"""Build the private, standalone implementation report from real game captures."""
from pathlib import Path
import base64
import html
import json

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'output'
shots=[('Heimatbasis','product-01-base.png'),('Werkbank','product-02-crafting-paused.png'),('Stationsmarkt','product-04-market.png'),('Rostwelt','product-06-satellite.png'),('Point-and-Click','controls-02-point-and-click.png')]
figures=[]
for i,(caption,filename) in enumerate(shots):
    source=OUT/filename
    assert source.exists(),source
    encoded=base64.b64encode(source.read_bytes()).decode()
    figures.append(f'<figure id="shot-{i}" {"" if i==0 else "hidden"}><img src="data:image/png;base64,{encoded}" alt="{caption}: echter Godot-Fensterlauf"><figcaption>{caption} · echte Spielansicht, keine Konzeptgrafik</figcaption></figure>')
product=json.loads((OUT/'product-result.json').read_text(encoding='utf-8'))
controls=json.loads((OUT/'control-result.json').read_text(encoding='utf-8'))
assert product['failed']==0 and controls['failed']==0
buttons=''.join(f'<button data-shot="{i}" aria-pressed="{str(i==0).lower()}">{html.escape(name)}</button>' for i,(name,_) in enumerate(shots))
document='''<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Sternenbürgerchen · Rostgrenze · Spielbarer Neustart</title>
<style>
:root{color-scheme:dark;--ink:#0b151c;--line:#30454d;--text:#e8ece8;--muted:#a4b7bb;--accent:#eba364;--cyan:#91cdca}*{box-sizing:border-box}body{margin:0;background:var(--ink);color:var(--text);font:16px/1.6 'Segoe UI',sans-serif}a{color:var(--cyan)}header,main,footer{max-width:1320px;margin:auto;padding:24px 32px}header{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);font-size:12px;letter-spacing:.12em}header span{color:var(--accent)}.intro{padding:36px 0 20px}.eyebrow{color:var(--accent);font-size:12px;letter-spacing:.2em}h1{font-size:clamp(36px,7vw,82px);line-height:1.02;letter-spacing:-.04em;margin:12px 0 20px}h2{font-size:24px;line-height:1.3;margin:0 0 16px}.lead{max-width:760px;color:var(--muted);font-size:19px}nav{display:flex;gap:6px;flex-wrap:wrap;margin:22px 0 12px}button{border:1px solid var(--line);border-radius:1px;background:#14232c;color:var(--text);padding:11px 16px;cursor:pointer}button[aria-pressed=true]{border-color:var(--cyan);color:var(--cyan)}button:hover{background:#263e48}figure{margin:0;border:1px solid var(--line)}figure[hidden]{display:none}figure img{width:100%;display:block}figcaption{padding:8px 14px;font-size:12px;color:var(--muted)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin:36px 0}.box{border-top:2px solid var(--line);padding:22px 0}p{margin:0 0 16px}ul,ol{padding-left:21px}li{margin:8px 0}.pill{display:inline-block;border:1px solid var(--line);padding:6px 10px;margin:4px 6px 0 0;font-size:13px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;border-bottom:1px solid var(--line);padding:10px 8px;vertical-align:top}th{color:var(--muted);font-weight:400}kbd{padding:2px 6px;border:1px solid var(--line);font-size:12px}aside{border-left:3px solid var(--accent);padding:8px 18px;color:var(--muted);margin:24px 0}.fine{color:var(--muted);font-size:13px}footer{border-top:1px solid var(--line);color:var(--muted);font-size:12px}@media(max-width:760px){header,main,footer{padding:20px}.grid{grid-template-columns:1fr}header{gap:20px}button{padding:9px 11px}.lead{font-size:17px}}
</style><header><b>STERNENBÜRGERCHEN</b><span>NEUSTART / N0 · N1 · N1a / 12.09.2026</span></header><main>
<section class="intro"><div class="eyebrow">ZWEI FREUNDE. EINE BASIS. EINE ZUKUNFT.</div><h1>Willkommen an<br>der Rostgrenze.</h1><p class="lead">Der erste Spielkreis ist da: Crew auswählen, Aufträge erledigen, Material bergen, handeln und an der eigenen Werkbank bessere Ausrüstung herstellen.</p><span class="pill">Point-and-Click</span><span class="pill">Rahmenauswahl</span><span class="pill">Solo + Koop-Probe</span><span class="pill">Godot 4.6.2</span></section>
<nav aria-label="Aktuelle Spielbilder">BUTTONS</nav>FIGURES
<div class="grid"><section class="box"><h2>Deine erste Reise</h2><ol><li>Auftragskonsole öffnen und Satellitenbergung annehmen.</li><li>Die Entersäbel wählen und zur Absturzstelle reisen.</li><li>Eine Person zum Satelliten schicken und bergen lassen.</li><li>Heimfliegen und Blackbox abgeben: 260 Credits und ein Bauplan.</li><li>Mit Ida an der Werkbank produzieren; Waren am Stationsmarkt verkaufen.</li></ol><p>Die Objekte in der Welt und ihre Symbole am linken Rand öffnen dieselben Funktionen. Geeignete Arbeiter, Materialbestand und Baupläne entscheiden über mögliche Aufträge.</p></section>
<section class="box"><h2>So steuerst du die Crew</h2><table><tr><th>Eingabe</th><th>Wirkung</th></tr><tr><td>Linksklick / <kbd>1</kbd> <kbd>2</kbd></td><td>Figur auswählen. Ein geöffnetes Arbeitsmenü bleibt erhalten.</td></tr><tr><td>Rahmen ziehen</td><td>Mehrere eigene Crewmitglieder wählen.</td></tr><tr><td>Rechtsklick</td><td>Laufziel für die Auswahl setzen.</td></tr><tr><td><kbd>WASD</kbd> / Pfeile</td><td>Ausschließlich die Kamera bewegen.</td></tr><tr><td><kbd>V</kbd> / Figur-Symbol</td><td>Freie Crewansicht oder Einzelansicht mit Kamerafolge.</td></tr><tr><td>Leertaste</td><td>Gemeinsame Pause; im Koop entscheidet der Host.</td></tr><tr><td><kbd>F5</kbd> / <kbd>F9</kbd></td><td>Speichern / Laden. Normales Beenden speichert; der nächste Start setzt fort.</td></tr></table></section></div>
<div class="grid"><section class="box"><h2>Modelle und Oberfläche</h2><p>Die weiße Helmfigur stammt aus dem Kenney Animated Characters Bundle. Sie hat Idle-, Lauf- und Arbeitsanimationen. Das Crewporträt ist ein Blender-Render desselben Modells.</p><p>Das bereitgestellte Schiff wurde zur lokalen <b>Entersäbel</b> umgebaut: <b>265.435 → 17.879 Dreiecke</b>. Die Basis hat jetzt umlaufende Wände, einen Eingang und eine transparente Front.</p><p>Das HUD nutzt schmale Leisten, eigene Linien-Icons, kompakte Auswahlkarten und kurze Tooltips. Aktiver Arbeiter, Reservierung, Arbeitsschritt und Sperrgründe bleiben erkennbar.</p><p class="fine">Bildreferenzen: <a href="https://www.gamestar.de/galerien/homeworld_3,136199.html">Homeworld 3</a>, <a href="https://www.kasedogames.com/ixion">IXION</a>, <a href="https://www.altchar.com/features/dune-spice-wars-preview-the-spice-must-flow-aZMO29j838Pg">Dune: Spice Wars</a>. Keine fremden UI-Grafiken übernommen.</p></section>
<section class="box"><h2>Was geprüft wurde</h2><table><tr><th>Bereich</th><th>Bestanden</th></tr><tr><td>Autoritativer Kern</td><td>100 / 100</td></tr><tr><td>Echter Produktpfad mit Maus</td><td>PRODUCT / PRODUCT</td></tr><tr><td>Point-and-Click und Kamera</td><td>CONTROLS / CONTROLS</td></tr><tr><td>Start, Beenden und Save-Fehlerschutz</td><td>10 / 10</td></tr><tr><td>Zwei echte Koop-Produktprozesse</td><td>48 / 48</td></tr></table><p class="fine">Koop-Nachweis auf demselben Rechner: getrennte Crewbesitzer, gemeinsame Pause, ältere Saves mit korrekter Synchronisierung, einmalige Auszahlung und Wiederverbinden. Screenshots und automatisierte Spielhandlungen sind technische Belege; menschliche Spieltests stehen aus.</p></section></div>
<section class="box"><h2>Der nächste Ausbau</h2><p>Der große Plan bleibt bestehen: kleiner Bunker und Bodenkampf, Verwundung/Evakuierung mit Rückkehr, baubare Räume und neue Crew, danach Raumkampf, Mining, Salvage, Transport und spätere kombinierte Operationen.</p><aside>Dieser Stand ist der spielbare Anfang. Kampf, Raumflug, PvP, Rekrutierung und baubare Erweiterungen sind noch nicht enthalten. Die jetzigen Wände und Felsen sind visuell; Hindernisnavigation und Deckung folgen mit dem nächsten Gameplay-Ausbau.</aside></section>
<section class="box"><h2>Lokal öffnen</h2><p><b>C:\\dev\\SternenBuergerchen-Neustart\\Spielen.cmd</b></p><p>Menü → Koop-Verbindung öffnet oder verbindet eine Sitzung. Normale Spielstände: <code>%APPDATA%\\SternenBuergerchen-Neustart\\campaign.json</code>.</p><p class="fine">Der separate Git-Branch heißt <code>codex/neustart-n0-n1</code>. Das lokale Schiff und dieser bebilderte Bericht liegen außerhalb des veröffentlichten Branch-Inhalts. Ein Clone verwendet ohne lokale Schiffsdatei das enthaltene Kenney-Shuttle.</p></section>
</main><footer>Lokaler, eigenständiger Bericht mit eingebetteten aktuellen Spielbildern. Die vollständige Umsetzungsgrenze steht im Projekt unter docs/IMPLEMENTATION_STATUS.md.</footer><script>document.querySelectorAll('[data-shot]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('figure').forEach(f=>f.hidden=f.id!=='shot-'+b.dataset.shot);document.querySelectorAll('[data-shot]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}))</script></html>'''
document=document.replace('BUTTONS',buttons).replace('FIGURES',''.join(figures)).replace('PRODUCT',str(product['checks'])).replace('CONTROLS',str(controls['checks']))
target=OUT/'ROSTGRENZE_SPIELSTAND.html'
target.write_text(document,encoding='utf-8')
print(target)
